'use client'
import { useCallback, useEffect, useRef, useState } from 'react'
import Link from 'next/link'
import { loadSvg } from '@/components/LineArtStage'

// Each product plays a short "reel" of line drawings (public/lineart/showcase/<key>.svg,
// generated by scripts/lineart/gen_showcase.py — keep keys in step with showcase_art.REELS).
interface Featured {
  name: string
  line: string
  stats: [{ v: string; l: string }, { v: string; l: string }]
  reel: { key: string; label: string }[]
  href: string
}

const PRODUCTS: Featured[] = [
  {
    name: 'Transformers',
    line: 'Padmount, substation and dry-type.',
    stats: [{ v: '100+ MVA', l: 'Max rating' }, { v: '345 kV', l: 'Max primary' }],
    reel: [{ key: 'padmount', label: 'Padmount' }, { key: 'substation', label: 'Substation' }, { key: 'dry-type', label: 'Dry-Type' }],
    href: '/products/transformers',
  },
  {
    name: 'Switchgear',
    line: 'Medium and low voltage, arc-resistant options.',
    stats: [{ v: '2.4–38 kV', l: 'Voltage class' }, { v: '40 kA', l: 'Interrupting' }],
    reel: [{ key: 'metal-enclosed', label: 'Metal-Enclosed' }, { key: 'pad-mounted', label: 'Pad-Mounted' }],
    href: '/products/switchgear',
  },
  {
    name: 'Switchboards',
    line: 'Custom LV distribution, delivered in weeks.',
    stats: [{ v: '4,000 A', l: 'Max current' }, { v: '600 V', l: 'System voltage' }],
    reel: [{ key: 'switchboard', label: 'Distribution Switchboard' }],
    href: '/products/switchboards',
  },
  {
    name: 'Load Banks',
    line: 'Prove generators and UPS under real load.',
    stats: [{ v: 'R · L · RL', l: 'Load types' }, { v: 'Portable', l: 'Or permanent' }],
    reel: [{ key: 'load-bank', label: 'Load Bank' }],
    href: '/products/load-banks',
  },
  {
    name: 'Remote Power Panels',
    line: 'Branch distribution right at the rack.',
    stats: [{ v: 'Front', l: 'Access' }, { v: 'Per-circuit', l: 'Monitoring' }],
    reel: [{ key: 'rpp', label: 'Remote Power Panel' }],
    href: '/products/remote-power-panels',
  },
  {
    name: 'Power Distribution Units',
    line: 'Step-down and isolation for critical loads.',
    stats: [{ v: 'Transformer', l: 'Based' }, { v: 'Branch', l: 'Monitoring' }],
    reel: [{ key: 'pdu', label: 'Power Distribution Unit' }],
    href: '/products/power-distribution-units',
  },
  {
    name: 'Control Panels',
    line: 'Automation and control, built to UL 508A.',
    stats: [{ v: 'UL 508A', l: 'Built to' }, { v: 'PLC · HMI', l: 'SCADA ready' }],
    reel: [{ key: 'control-panel', label: 'Control Panel' }],
    href: '/products/control-panels',
  },
]

const SHOT_MS = 5200
const src = (key: string) => `/lineart/showcase/${key}.svg`

export default function FeaturedProducts() {
  const rootRef = useRef<HTMLElement>(null)
  const [active, setActive] = useState(0)
  const [playing, setPlaying] = useState(true)
  const [hovered, setHovered] = useState(false)
  const [seen, setSeen] = useState(false)
  const [markup, setMarkup] = useState<Record<string, string>>({})
  const [elapsed, setElapsed] = useState(0)
  const elapsedRef = useRef(0)

  const product = PRODUCTS[active]
  const total = product.reel.length * SHOT_MS
  const shot = Math.max(0, Math.min(product.reel.length - 1, Math.floor(elapsed / SHOT_MS)))
  const item = product.reel[shot]
  const running = playing && !hovered && seen

  useEffect(() => {
    const el = rootRef.current
    if (!el) return
    const obs = new IntersectionObserver(([e]) => {
      if (!e.isIntersecting) return
      setSeen(true)
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) setPlaying(false)
    }, { threshold: 0.2 })
    obs.observe(el)
    return () => obs.disconnect()
  }, [])

  // Load every drawing once the section is close; they are small.
  useEffect(() => {
    if (!seen) return
    let live = true
    PRODUCTS.flatMap(p => p.reel).forEach(r => {
      loadSvg(src(r.key)).then(t => { if (live) setMarkup(m => (m[r.key] ? m : { ...m, [r.key]: t })) })
    })
    return () => { live = false }
  }, [seen])

  const seek = useCallback((productIndex: number, ms: number) => {
    elapsedRef.current = ms
    setElapsed(ms)
    setActive((productIndex + PRODUCTS.length) % PRODUCTS.length)
  }, [])

  // Video-style clock: run through this product's reel, then move to the next product.
  useEffect(() => {
    if (!running) return
    let last = performance.now()
    let raf = 0
    const tick = (now: number) => {
      // rAF timestamps can precede the performance.now() taken at start; never step backwards
      const next = elapsedRef.current + Math.max(0, now - last)
      last = now
      if (next >= total) {
        seek(active + 1, 0)
        return
      }
      elapsedRef.current = next
      setElapsed(next)
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [running, total, active, seek])

  const progress = Math.min(1, elapsed / total)

  return (
    <section
      ref={rootRef}
      className="fp-section"
      aria-labelledby="fp-title"
    >
      <div className="container">
        <div className="fp-head">
          <div>
            <div className="label">Featured Products</div>
            <h2 id="fp-title">Power Distribution, <em>Built to Spec.</em></h2>
          </div>
          <Link href="/products" className="btn btn-outline-blue">All Products →</Link>
        </div>

        <div className="fp-layout" onMouseEnter={() => setHovered(true)} onMouseLeave={() => setHovered(false)}>
          <div className={`fp-stage${seen ? ' is-in' : ''}`}>
            <span className="la-corner la-tl" aria-hidden="true" />
            <span className="la-corner la-tr" aria-hidden="true" />
            <span className="la-corner la-bl" aria-hidden="true" />
            <span className="la-corner la-br" aria-hidden="true" />

            <div className="fp-copy" key={active}>
              <div className="fp-count"><span>{String(active + 1).padStart(2, '0')}</span> / {String(PRODUCTS.length).padStart(2, '0')}</div>
              <h3 className="fp-name" aria-live="polite">
                {product.name.split(' ').map((w, i) => (
                  <span key={i} className="fp-word" style={{ animationDelay: `${i * 90}ms` }}>{w}&nbsp;</span>
                ))}
              </h3>
              <p className="fp-line">{product.line}</p>
              <dl className="fp-stats">
                {product.stats.map((s, i) => (
                  <div key={s.l} style={{ animationDelay: `${420 + i * 120}ms` }}>
                    <dt>{s.l}</dt><dd>{s.v}</dd>
                  </div>
                ))}
              </dl>
              <Link href={product.href} className="fp-cta">Explore {product.name} <span aria-hidden="true">→</span></Link>
            </div>

            <div className="fp-drawing" aria-hidden="true">
              <div
                key={`${active}-${shot}`}
                className={`la-svg${markup[item.key] ? ' on' : ''}`}
                dangerouslySetInnerHTML={markup[item.key] ? { __html: markup[item.key] } : undefined}
              />
            </div>

            <div className="fp-bar">
              <button
                type="button"
                className="fp-play"
                onClick={() => setPlaying(p => !p)}
                aria-label={playing ? 'Pause product showcase' : 'Play product showcase'}
              >
                {playing ? (
                  <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><rect x="6" y="5" width="4" height="14" rx="1" /><rect x="14" y="5" width="4" height="14" rx="1" /></svg>
                ) : (
                  <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M7 5v14l12-7z" /></svg>
                )}
              </button>
              <div className="fp-reel">
                {product.reel.map((r, i) => (
                  <button
                    key={r.key}
                    type="button"
                    className={i === shot ? 'on' : ''}
                    onClick={() => seek(active, i * SHOT_MS)}
                  >
                    {r.label}
                  </button>
                ))}
              </div>
              <div className="fp-track" aria-hidden="true"><span style={{ transform: `scaleX(${progress})` }} /></div>
              <span className="fp-dwg">DWG CE-FP-{String(active + 1).padStart(2, '0')}{product.reel.length > 1 ? `.${shot + 1}` : ''}</span>
            </div>
          </div>

          <ol className="fp-list" aria-label="Featured products">
            {PRODUCTS.map((p, i) => (
              <li key={p.name}>
                <button
                  type="button"
                  className={i === active ? 'on' : ''}
                  aria-current={i === active ? 'true' : undefined}
                  onClick={() => seek(i, 0)}
                >
                  <span className="fp-li-num">{String(i + 1).padStart(2, '0')}</span>
                  <span className="fp-li-name">{p.name}</span>
                  <span className="fp-li-meta">{p.stats[0].v}</span>
                  <span className="fp-li-track" aria-hidden="true">
                    <span style={{ transform: `scaleX(${i === active ? progress : i < active ? 1 : 0})` }} />
                  </span>
                </button>
              </li>
            ))}
          </ol>
        </div>
      </div>
    </section>
  )
}
